package com.johnny.hotel;
import com.johnny.hotel.businessdate.*;import com.johnny.hotel.mapper.SysAuditLogMapper;import com.johnny.hotel.nightaudit.*;import org.junit.jupiter.api.Test;import java.time.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class NightAuditStateServiceTest {
 @Test void beginLocksBusinessDatePrechecksThenCloses(){var dates=mock(BusinessDateMapper.class);var db=mock(NightAuditMapper.class);var audits=mock(SysAuditLogMapper.class);var d=LocalDate.of(2026,9,22);when(dates.lockExclusive()).thenReturn(BusinessDateControl.builder().businessDate(d).state("OPEN").build());when(db.insert(any())).thenAnswer(i->{i.<NightAuditRun>getArgument(0).setId(9L);return 1;});when(db.ready(9L)).thenReturn(1);when(dates.beginClosing(d)).thenReturn(1);when(db.byDate(d)).thenReturn(null,NightAuditRun.builder().id(9L).businessDate(d).status("STARTING").build());var run=new NightAuditStateService(dates,db,audits,Clock.fixed(Instant.parse("2026-09-22T22:00:00Z"),ZoneOffset.UTC)).begin("request",3L);assertEquals(9L,run.getId());var order=inOrder(dates,db);order.verify(dates).lockExclusive();order.verify(db).byRequest("request");order.verify(db).byDate(d);order.verify(db).insert(any());order.verify(db).resolveAll(eq(9L),any());order.verify(db).pendingArrivals(d);order.verify(db).overdueStays(d);order.verify(db).blockers(9L);order.verify(db).ready(9L);order.verify(dates).beginClosing(d);}
 @Test void manualBlockerKeepsBusinessDateOpen(){var dates=mock(BusinessDateMapper.class);var db=mock(NightAuditMapper.class);var audits=mock(SysAuditLogMapper.class);var d=LocalDate.of(2026,9,22);var run=NightAuditRun.builder().id(9L).businessDate(d).status("STARTING").build();when(dates.lockExclusive()).thenReturn(BusinessDateControl.builder().businessDate(d).state("OPEN").build());when(db.byDate(d)).thenReturn(run,NightAuditRun.builder().id(9L).businessDate(d).status("BLOCKED").build());when(db.pendingArrivals(d)).thenReturn(java.util.List.of(44L));when(db.blockers(9L)).thenReturn(java.util.List.of(NightAuditBlocker.builder().objectId(44L).build()));var result=new NightAuditStateService(dates,db,audits,Clock.systemUTC()).begin("request",3L);assertEquals("BLOCKED",result.getStatus());verify(db).precheckBlocked(9L,"1 precheck blocker(s)");verify(dates,never()).beginClosing(any());}
 @Test void finalAdvanceIsAtomicLastStateTransition(){var dates=mock(BusinessDateMapper.class);var db=mock(NightAuditMapper.class);var audits=mock(SysAuditLogMapper.class);var d=LocalDate.of(2026,9,22);var run=NightAuditRun.builder().id(9L).businessDate(d).requestKey("request").status("RUNNING").processingToken("token").build();when(dates.lockExclusive()).thenReturn(BusinessDateControl.builder().businessDate(d).state("CLOSING").build());when(db.lock(9L)).thenReturn(run);when(db.blockers(9L)).thenReturn(java.util.List.of());when(dates.advanceHistory(eq(d),eq(d.plusDays(1)),eq(3L),any())).thenReturn(1);when(dates.advance(d,d.plusDays(1))).thenReturn(1);when(db.complete(eq(9L),eq("token"),any())).thenReturn(1);when(audits.insert(any())).thenReturn(1);when(db.byRequest("request")).thenReturn(NightAuditRun.builder().id(9L).businessDate(d).status("COMPLETED").build());assertEquals("COMPLETED",new NightAuditStateService(dates,db,audits,Clock.systemUTC()).finish(9L,"token",3L).getStatus());var order=inOrder(dates,db,audits);order.verify(dates).lockExclusive();order.verify(db).lock(9L);order.verify(db).blockers(9L);order.verify(dates).advanceHistory(eq(d),eq(d.plusDays(1)),eq(3L),any());order.verify(dates).advance(d,d.plusDays(1));order.verify(db).complete(eq(9L),eq("token"),any());order.verify(audits).insert(any());}
}
